using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        HttpRequestMessage? captured = null;
        string? capturedBody = null;
        var handler = new StubHandler(async request =>
        {
            captured = request;
            capturedBody = await request.Content!.ReadAsStringAsync();
            return JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""");
        });
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, captured!.Method);
        Assert.Equal("/v1/authorizations", captured.RequestUri!.AbsolutePath);
        using var document = JsonDocument.Parse(capturedBody!);
        var root = document.RootElement;
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(42.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_reported_as_approved()
    {
        var gateway = GatewayThatReturns(HttpStatusCode.OK, """{"status":"approved"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_reported_as_declined()
    {
        var gateway = GatewayThatReturns(HttpStatusCode.OK, """{"status":"declined"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_payment_required_response_means_the_provider_refused_the_payment()
    {
        var gateway = GatewayThatReturns(HttpStatusCode.PaymentRequired, """{"status":"refused"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_value_is_treated_as_declined()
    {
        var gateway = GatewayThatReturns(HttpStatusCode.OK, """{"status":"pending"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_empty_body_on_success_is_treated_as_declined()
    {
        var gateway = GatewayThatReturns(HttpStatusCode.OK, "null");

        var outcome = await gateway.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Any_other_non_success_status_bubbles_up_as_an_error(HttpStatusCode statusCode)
    {
        var gateway = GatewayThatReturns(statusCode, "{}");

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-7", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpPaymentGateway GatewayThatReturns(HttpStatusCode statusCode, string jsonBody)
    {
        var handler = new StubHandler(_ => Task.FromResult(JsonResponse(statusCode, jsonBody)));
        return new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });
    }

    private static HttpResponseMessage JsonResponse(HttpStatusCode statusCode, string jsonBody)
        => new(statusCode) { Content = JsonContent.Create(JsonDocument.Parse(jsonBody).RootElement) };

    private sealed class StubHandler(Func<HttpRequestMessage, Task<HttpResponseMessage>> respond) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            => respond(request);
    }
}

